  function keepsHandMadePreview() { return isAdminMode() && isPrintDesign(); }
  // The design's caption prompt, for the AI caption writer to start from.
  window.__TMKE_CAPTION_PROMPT__ = function () { return (state.canvas && state.canvas.captionPrompt) || ""; };
  window.__TMKE_IS_PRINT__ = function () { try { return isPrintDesign(); } catch (_) { return false; } };
  window.__TMKE_IS_MOCKUP__ = function () { try { return isMockupDesign(); } catch (_) { return false; } };
  window.__TMKE_SIZE_FAMILY__ = function (w, h) { try { return sizeFamily(w, h); } catch (_) { return null; } };
  // Page one of the design as it stands on screen, for Regenerate previews.
  window.__TMKE_OPEN_PAGE_ONE__ = function () {
    const pg = (state.pages && state.pages[0]) || { canvas: state.canvas, elements: state.elements };
    return { canvas: deep(pg.canvas), elements: deep(pg.elements) };
  };
  // Page two of the design on screen, for its back preview; null if it has one page.
  // Every page of the open design, for a picture of each (Regenerate previews).
  window.__TMKE_OPEN_PAGES__ = function () {
    return (state.pages || []).map(function (pg) { return { canvas: deep(pg.canvas), elements: deep(pg.elements) }; });
  };
  window.__TMKE_OPEN_PAGE_TWO__ = function () {
    const pg = state.pages && state.pages[1];
    return pg ? { canvas: deep(pg.canvas), elements: deep(pg.elements) } : null;
  };
