      const sx = half ? Math.round(full.width / 2) : 0, sw = full.width - sx;
      const c = document.createElement("canvas"); c.width = sw; c.height = full.height;
      c.getContext("2d").drawImage(full, sx, 0, sw, full.height, 0, 0, sw, full.height);
